function setCandyTierFilter(tier){soundClick();currentCandyTier=tier;document.querySelectorAll(".candy-tier-filter-bar .tier-pill").forEach(btn=>btn.classList.remove("active"));const activeBtn=document.getElementById(`tierPill_${tier}`);if(activeBtn)activeBtn.classList.add("active");recentCandyWordsHistory=[];generateCandyBoard();const labelMap={all:"全部高级词库",cet4:"CET-4 核心词库",cet6:"CET-6 & 考研高阶词库",ielts:"雅思托福 & 菁英词库"};showToast(`🎯 已切换消消乐词库：${labelMap[tier]||tier}`)}function startCandyMatchGame(){soundClick();const gameBox=document.getElementById("candyMatchGameBox");if(gameBox)gameBox.style.display="block";const settleArea=document.getElementById("matchSettlementArea");if(settleArea){settleArea.style.display="none";settleArea.innerHTML=""}const grid=document.getElementById("candyGrid");if(grid)grid.style.display="grid";matchRemaining=45;matchScore=0;matchCombo=1;matchWave=1;matchActiveTile=null;document.getElementById("matchScoreVal").textContent=matchScore;document.getElementById("matchComboVal").textContent=`x${matchCombo}`;document.getElementById("matchTimerVal").textContent=`${matchRemaining}s`;document.getElementById("matchWaveVal").textContent=`WAVE ${matchWave}`;document.getElementById("matchTimerBar").style.width="100%";clearInterval(matchTimerInterval);matchTimerInterval=setInterval(()=>{matchRemaining--;const timerVal=document.getElementById("matchTimerVal");const timerBar=document.getElementById("matchTimerBar");if(timerVal)timerVal.textContent=`${matchRemaining}s`;if(timerBar)timerBar.style.width=`${matchRemaining/45*100}%`;if(matchRemaining<=0){endCandyMatchGame()}},1e3);generateCandyBoard();showToast("🍬 消消乐已开局！45秒极速配对挑战开始！")}function generateCandyBoard(){const grid=document.getElementById("candyGrid");if(!grid)return;grid.innerHTML="";matchActiveTile=null;let validWords=words.filter(w=>{const raw=chineseDict[w];if(!raw||typeof raw!=="string")return false;const cleanZh=raw.replace(/\(考纲词汇\)|（考纲词汇）/g,"").trim();if(!cleanZh||cleanZh.toLowerCase()===w.toLowerCase())return false;return/[\u4e00-\u9fa5]/.test(cleanZh)});if(currentCandyTier!=="all"&&typeof wordTierDict!=="undefined"){const tiered=validWords.filter(w=>(wordTierDict[w]||"cet4")===currentCandyTier);if(tiered.length>=6){validWords=tiered}}if(recentCandyWordsHistory.length>=validWords.length-12||recentCandyWordsHistory.length>80){recentCandyWordsHistory=[]}const unpickedWords=validWords.filter(w=>!recentCandyWordsHistory.includes(w));const candidatePool=unpickedWords.length>=6?unpickedWords:validWords;const marked=getMarkedWords().map(m=>m[0]).filter(w=>{const raw=chineseDict[w];if(!raw||typeof raw!=="string")return false;const cleanZh=raw.replace(/\(考纲词汇\)|（考纲词汇）/g,"").trim();return cleanZh&&/[\u4e00-\u9fa5]/.test(cleanZh)&&cleanZh.toLowerCase()!==w.toLowerCase()&&!recentCandyWordsHistory.includes(w)});let pool=[];if(marked.length>0){const pickMarkedCount=Math.min(2,marked.length);const shuffledMarked=[...marked].sort(()=>.5-Math.random()).slice(0,pickMarkedCount);pool.push(...shuffledMarked)}const freshWords=candidatePool.filter(w=>!pool.includes(w)).sort(()=>.5-Math.random());while(pool.length<6&&freshWords.length>0){pool.push(freshWords.pop())}pool.forEach(w=>{recentCandyWordsHistory.push(w)});const tiles=[];const colorIndices=Array.from({length:12},(_,i)=>i).sort(()=>.5-Math.random());let colorPointer=0;pool.forEach(word=>{const rawDef=chineseDict[word]||"";const rawCn=rawDef.replace(/\(考纲词汇\)|（考纲词汇）/g,"").trim();let cn=rawCn.split(/[,;，；]/)[0].replace(/^[a-z]+\.\s*/i,"").trim();if(!cn||!/[\u4e00-\u9fa5]/.test(cn)||cn.toLowerCase()===word.toLowerCase()){cn=rawCn}if(!cn||!/[\u4e00-\u9fa5]/.test(cn)||cn.toLowerCase()===word.toLowerCase()){return}const enColorClass=`color-theme-${colorIndices[colorPointer++%12]}`;const cnColorClass=`color-theme-${colorIndices[colorPointer++%12]}`;tiles.push({word:word,type:"en",text:word,colorClass:enColorClass});tiles.push({word:word,type:"cn",text:cn,colorClass:cnColorClass})});tiles.sort(()=>.5-Math.random());tiles.forEach(t=>{const el=document.createElement("div");el.className=`candy-tile ${t.colorClass}`;el.dataset.word=t.word;el.dataset.type=t.type;el.innerHTML=`\n      <span class="tile-lang-badge">${t.type==="en"?"ENGLISH":"CHINESE"}</span>\n      <span class="tile-word-text">${escapeHtml(t.text)}</span>\n    `;el.onclick=()=>handleCandyTileClick(el);grid.appendChild(el)})}function handleCandyTileClick(el){if(el.classList.contains("pop-match")||el===matchActiveTile)return;soundClick();if(!matchActiveTile){matchActiveTile=el;el.classList.add("selected");return}const first=matchActiveTile;const second=el;matchActiveTile=null;first.classList.remove("selected");if(first.dataset.word===second.dataset.word&&first.dataset.type!==second.dataset.type){soundSuccess();first.classList.add("pop-match");second.classList.add("pop-match");matchScore+=10*matchCombo;matchCombo++;playerProfile.xp+=10;saveToStorage(STORAGE_KEYS.PROFILE,playerProfile);updateBadges();triggerCloudSync();const scVal=document.getElementById("matchScoreVal");const cbVal=document.getElementById("matchComboVal");if(scVal)scVal.textContent=matchScore;if(cbVal)cbVal.textContent=`x${matchCombo}`;setTimeout(()=>{const remaining=document.querySelectorAll(".candy-tile:not(.pop-match)");if(remaining.length===0){matchWave++;const wvVal=document.getElementById("matchWaveVal");if(wvVal)wvVal.textContent=`WAVE ${matchWave}`;showToast(`🎉 WAVE ${matchWave-1} 全清！波次奖励 +30 XP`);playerProfile.xp+=30;generateCandyBoard()}},400)}else{soundFailure();first.classList.add("shake-error");second.classList.add("shake-error");const wrongW1=first.dataset.word;const wrongW2=second.dataset.word;addMark(wrongW1);addMark(wrongW2);matchCombo=1;playerProfile.hp=Math.max(0,playerProfile.hp-5);const cbVal=document.getElementById("matchComboVal");if(cbVal)cbVal.textContent=`x1`;updateBadges();triggerCloudSync();showToast(`⚠️ 配对错误！[${wrongW1}] 与 [${wrongW2}] Mark +1 惩罚！`);setTimeout(()=>{first.classList.remove("shake-error");second.classList.remove("shake-error")},450)}}function endCandyMatchGame(){clearInterval(matchTimerInterval);soundSuccess();const grid=document.getElementById("candyGrid");if(grid)grid.style.display="none";const settleArea=document.getElementById("matchSettlementArea");if(settleArea){settleArea.style.display="block";settleArea.innerHTML=`\n      <div style="background:var(--paper-surface-sub); border:2px solid var(--brand-primary); border-radius:var(--radius-lg); padding:22px; text-align:center; animation:fadeIn 0.3s ease-out;">\n        <div style="font-size:36px; margin-bottom:8px;">🏁</div>\n        <div style="font-size:18px; font-weight:900; color:var(--brand-primary); margin-bottom:4px;">TIME UP · 挑战结算</div>\n        <div style="font-size:13px; color:var(--text-secondary); margin-bottom:16px;">45 秒极速配对挑战结束！</div>\n        \n        <div style="display:grid; grid-template-columns:repeat(3, 1fr); gap:10px; margin-bottom:18px;">\n          <div style="background:var(--paper-surface); border:1px solid var(--paper-border); padding:10px; border-radius:var(--radius-sm);">\n            <div style="font-size:11px; color:var(--text-secondary);">最终得分</div>\n            <div style="font-size:18px; font-weight:800; color:var(--brand-accent);">${matchScore} 分</div>\n          </div>\n          <div style="background:var(--paper-surface); border:1px solid var(--paper-border); padding:10px; border-radius:var(--radius-sm);">\n            <div style="font-size:11px; color:var(--text-secondary);">通关波次</div>\n            <div style="font-size:18px; font-weight:800; color:var(--brand-success);">WAVE ${matchWave}</div>\n          </div>\n          <div style="background:var(--paper-surface); border:1px solid var(--paper-border); padding:10px; border-radius:var(--radius-sm);">\n            <div style="font-size:11px; color:var(--text-secondary);">最高连击</div>\n            <div style="font-size:18px; font-weight:800; color:var(--brand-primary);">x${matchCombo}</div>\n          </div>\n        </div>\n\n        <div style="display:flex; gap:10px;">\n          <button class="btn btn-primary" style="flex:2; height:42px; font-weight:800;" onclick="startCandyMatchGame()">\n            ⚡ 立即再来一局 (Play Again)\n          </button>\n          <button class="btn btn-secondary" style="flex:1; height:42px;" onclick="abortMatchGame()">\n            🚪 退出对局\n          </button>\n        </div>\n      </div>\n    `}}function abortMatchGame(){soundClick();clearInterval(matchTimerInterval);const gameBox=document.getElementById("candyMatchGameBox");if(gameBox)gameBox.style.display="none";const settleArea=document.getElementById("matchSettlementArea");if(settleArea){settleArea.style.display="none";settleArea.innerHTML=""}const grid=document.getElementById("candyGrid");if(grid)grid.style.display="grid";showToast("🚪 已退出消消乐对局")}